"""Independent reference for the A-level packet processing (written from PROTOCOL.md)."""
import hashlib

MAX62 = 2**62-1
MAX60 = 2**60

class Err(Exception):
    def __init__(self, code, offset):
        self.code=code; self.offset=offset

def varint(v):
    if v < 64: return bytes([v])
    if v < 16384: return bytes([0x40|(v>>8), v&0xFF])
    if v < 2**30: return bytes([0x80|(v>>24)]) + (v&0xFFFFFF).to_bytes(3,'big')
    return bytes([0xc0|(v>>56)]) + (v&((1<<56)-1)).to_bytes(7,'big')

def dec_varint(b, i):
    n = 1 << (b[i]>>6)
    if i+n > len(b): raise Err('FRAME_ENCODING_ERROR', -1)
    v = b[i] & 0x3f
    for j in range(1,n): v = (v<<8)|b[i+j]
    return v, i+n

def minimal(b, i):
    """returns (value, width, next)"""
    v, j = dec_varint(b, i)
    width = j-i
    if width != len(varint(v)): raise Err('FRAME_ENCODING_ERROR', -1)
    return v, width, j

class State:
    def __init__(self, limits, local):
        self.limits = limits
        self.local = local
        self.streams = {}
        self.ack = []          # list of [start,end)
        self.crypto = {}       # offset -> byte
        self.used = 0
        self.opened = {'bidi':0,'uni':0}
        self.send_max_data = 0
        self.send_max_streams = {'bidi':0,'uni':0}
        self.seen = set()
        self.largest = None

    def copy(self):
        import copy
        s = State(self.limits, self.local)
        s.streams = copy.deepcopy(self.streams)
        s.ack = copy.deepcopy(self.ack)
        s.crypto = dict(self.crypto)
        s.used = self.used
        s.opened = dict(self.opened)
        s.send_max_data = self.send_max_data
        s.send_max_streams = dict(self.send_max_streams)
        s.seen = set(self.seen)
        s.largest = self.largest
        return s

def merge(ivs):
    out=[]
    for s,e in sorted(ivs):
        if out and s <= out[-1][1]: out[-1][1]=max(out[-1][1],e)
        else: out.append([s,e])
    return out

def add_iv(ivs, s, e):
    ivs.append([s,e])
    return merge(ivs)

def check_ref(st, sid, receive, offset):
    t = sid & 3
    idx = sid >> 2
    if t == 0:
        if idx >= st.limits['bidi']: raise Err('STREAM_LIMIT_ERROR', offset)
        st.opened['bidi'] = max(st.opened['bidi'], idx+1)
    elif t == 2:
        if not receive: raise Err('STREAM_STATE_ERROR', offset)
        if idx >= st.limits['uni']: raise Err('STREAM_LIMIT_ERROR', offset)
        st.opened['uni'] = max(st.opened['uni'], idx+1)
    elif t == 1:
        if idx >= st.local['bidi']: raise Err('STREAM_STATE_ERROR', offset)
    else:
        if receive: raise Err('STREAM_STATE_ERROR', offset)
        if idx >= st.local['uni']: raise Err('STREAM_STATE_ERROR', offset)

def stream_of(st, sid):
    if sid not in st.streams:
        st.streams[sid] = {'high':0,'final':None,'reset':None,'stop':None,'send_max':0,'data':{}}
    return st.streams[sid]

def apply_flow(st, s, end, offset):
    cand = max(s['high'], end)
    if cand > st.limits['stream']: raise Err('FLOW_CONTROL_ERROR', offset)
    newused = st.used + (cand - s['high'])
    if newused > st.limits['connection']: raise Err('FLOW_CONTROL_ERROR', offset)
    if cand != s['high']:
        st.used = newused
        s['high'] = cand

def process_payload(payload, st):
    """returns the canonical payload bytes; raises Err"""
    if len(payload) == 0: raise Err('FRAME_ENCODING_ERROR', 0)
    i = 0
    canon = b''
    while i < len(payload):
        start = i
        try:
            typ, width, i = minimal(payload, i)
        except Err:
            raise Err('FRAME_ENCODING_ERROR', start)
        if typ > 0x1e and typ not in (0x30, 0x31): raise Err('FRAME_ENCODING_ERROR', start)
        if typ in (0x07, 0x1e): raise Err('PROTOCOL_VIOLATION', start)
        if typ not in (0x00,0x01,0x02,0x03,0x06,0x1c) and typ != 0x1d:
            raise Err('PROTOCOL_VIOLATION', start)   # application only (level A)
        # decode body
        f = {'type':typ}
        if typ in (0x00,0x01):
            pass
        elif typ in (0x02,0x03):
            try:
                largest,i = dec_varint(payload,i); delay,i = dec_varint(payload,i)
                count,i = dec_varint(payload,i); first,i = dec_varint(payload,i)
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            if first > largest: raise Err('FRAME_ENCODING_ERROR', start)
            pairs=[]
            for _ in range(count):
                try:
                    gap,i = dec_varint(payload,i); rng,i = dec_varint(payload,i)
                except Err: raise Err('FRAME_ENCODING_ERROR', start)
                pairs.append((gap,rng))
            ecnv = []
            if typ == 0x03:
                try:
                    for _ in range(3): v,i = dec_varint(payload,i); ecnv.append(v)
                except Err: raise Err('FRAME_ENCODING_ERROR', start)
            f.update(largest=largest, delay=delay, count=count, first=first, pairs=pairs, ecn=ecnv)
        elif typ == 0x04:
            try:
                sid,i = dec_varint(payload,i); err,i = dec_varint(payload,i); fin,i = dec_varint(payload,i)
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            f.update(sid=sid, err=err, fin=fin)
        elif typ == 0x05:
            try:
                sid,i = dec_varint(payload,i); err,i = dec_varint(payload,i)
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            f.update(sid=sid, err=err)
        elif typ == 0x06:
            try:
                off,i = dec_varint(payload,i); ln,i = dec_varint(payload,i)
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            if i+ln > len(payload): raise Err('FRAME_ENCODING_ERROR', start)
            f.update(off=off, ln=ln, data=payload[i:i+ln]); i += ln
        elif 0x08 <= typ <= 0x0f:
            fin = bool(typ & 1); haslen = bool(typ & 2); hasoff = bool(typ & 4)
            try:
                sid,i = dec_varint(payload,i)
                off = 0
                if hasoff: off,i = dec_varint(payload,i)
                if haslen:
                    ln,i = dec_varint(payload,i)
                    if i+ln > len(payload): raise Err('FRAME_ENCODING_ERROR', start)
                    data = payload[i:i+ln]; i += ln
                else:
                    ln = len(payload)-i; data = payload[i:i+ln]; i += ln
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            f.update(sid=sid, off=off, ln=ln, data=data, fin=fin, hasoff=hasoff, haslen=haslen)
        elif typ in (0x10,0x12,0x13,0x14,0x16,0x17):
            try: v,i = dec_varint(payload,i)
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            f.update(v=v)
        elif typ == 0x11:
            try:
                sid,i = dec_varint(payload,i); v,i = dec_varint(payload,i)
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            f.update(sid=sid, v=v)
        elif typ == 0x15:
            try:
                sid,i = dec_varint(payload,i); v,i = dec_varint(payload,i)
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            f.update(sid=sid, v=v)
        elif typ == 0x18:
            try:
                seq,i = dec_varint(payload,i); rpt,i = dec_varint(payload,i)
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            if i+1 > len(payload): raise Err('FRAME_ENCODING_ERROR', start)
            cl = payload[i]; i += 1
            if i+cl+16 > len(payload): raise Err('FRAME_ENCODING_ERROR', start)
            cid = payload[i:i+cl]; i += cl
            tok = payload[i:i+16]; i += 16
            f.update(seq=seq, rpt=rpt, cl=cl, cid=cid, tok=tok)
        elif typ == 0x19:
            try: seq,i = dec_varint(payload,i)
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            f.update(seq=seq)
        elif typ in (0x1a,0x1b):
            if i+8 > len(payload): raise Err('FRAME_ENCODING_ERROR', start)
            f['data']=payload[i:i+8]; i += 8
        elif typ == 0x1c:
            try:
                ec,i = dec_varint(payload,i); tt,i = dec_varint(payload,i); rl,i = dec_varint(payload,i)
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            if i+rl > len(payload): raise Err('FRAME_ENCODING_ERROR', start)
            f.update(ec=ec, tt=tt, rl=rl, reason=payload[i:i+rl]); i += rl
        elif typ == 0x1d:
            try:
                ec,i = dec_varint(payload,i); rl,i = dec_varint(payload,i)
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            if i+rl > len(payload): raise Err('FRAME_ENCODING_ERROR', start)
            f.update(ec=ec, rl=rl, reason=payload[i:i+rl]); i += rl
        elif typ == 0x30:
            f['data']=payload[i:]; i = len(payload)
        elif typ == 0x31:
            try: ln,i = dec_varint(payload,i)
            except Err: raise Err('FRAME_ENCODING_ERROR', start)
            if i+ln > len(payload): raise Err('FRAME_ENCODING_ERROR', start)
            f.update(ln=ln, data=payload[i:i+ln]); i += ln
        # semantics
        t = typ
        if t in (0x02,0x03):
            low = f['largest']-f['first']
            st.ack = add_iv(st.ack, low, f['largest']+1)
            for gap,rng in f['pairs']:
                if low < gap+2: raise Err('FRAME_ENCODING_ERROR', start)
                high = low-gap-2
                if rng > high: raise Err('FRAME_ENCODING_ERROR', start)
                newlow = high-rng
                st.ack = add_iv(st.ack, newlow, high+1)
                low = newlow
        elif t == 0x04:
            check_ref(st, f['sid'], True, start)
            s = stream_of(st, f['sid'])
            if f['fin'] < s['high']: raise Err('FINAL_SIZE_ERROR', start)
            if s['final'] is not None and s['final'] != f['fin']: raise Err('FINAL_SIZE_ERROR', start)
            if s['final'] is None: s['final']=f['fin']
            apply_flow(st, s, f['fin'], start)
            if s['reset'] is None: s['reset']=f['err']
        elif t == 0x05:
            check_ref(st, f['sid'], False, start)
            s = stream_of(st, f['sid'])
            if s['stop'] is None: s['stop']=f['err']
        elif t == 0x06:
            if f['off'] > MAX62 - f['ln']: raise Err('FRAME_ENCODING_ERROR', start)
            for k,b in enumerate(f['data']):
                o = f['off']+k
                if o in st.crypto and st.crypto[o] != b: raise Err('PROTOCOL_VIOLATION', start)
            for k,b in enumerate(f['data']): st.crypto[f['off']+k]=b
        elif 0x08 <= t <= 0x0f:
            check_ref(st, f['sid'], True, start)
            if f['off'] > MAX62 - f['ln']: raise Err('FRAME_ENCODING_ERROR', start)
            end = f['off']+f['ln']
            s = stream_of(st, f['sid'])
            if s['final'] is not None:
                if end > s['final']: raise Err('FINAL_SIZE_ERROR', start)
                if f['fin'] and end != s['final']: raise Err('FINAL_SIZE_ERROR', start)
            elif f['fin']:
                if end < s['high']: raise Err('FINAL_SIZE_ERROR', start)
                s['final']=end
            apply_flow(st, s, end, start)
            if s['reset'] is None:
                for k,b in enumerate(f['data']):
                    o = f['off']+k
                    if o in s['data'] and s['data'][o] != b: raise Err('PROTOCOL_VIOLATION', start)
                for k,b in enumerate(f['data']): s['data'][f['off']+k]=b
        elif t == 0x10:
            st.send_max_data = max(st.send_max_data, f['v'])
        elif t == 0x11:
            check_ref(st, f['sid'], False, start)
            s = stream_of(st, f['sid'])
            s['send_max'] = max(s['send_max'], f['v'])
        elif t in (0x12,0x13):
            if f['v'] > MAX60: raise Err('FRAME_ENCODING_ERROR', start)
            k = 'bidi' if t==0x12 else 'uni'
            st.send_max_streams[k] = max(st.send_max_streams[k], f['v'])
        elif t == 0x15:
            check_ref(st, f['sid'], True, start)
            stream_of(st, f['sid'])
        elif t in (0x16,0x17):
            if f['v'] > MAX60: raise Err('FRAME_ENCODING_ERROR', start)
        elif t == 0x18:
            if f['rpt'] > f['seq']: raise Err('FRAME_ENCODING_ERROR', start)
            if f['cl'] < 1 or f['cl'] > 20: raise Err('FRAME_ENCODING_ERROR', start)
        # canonical encoding
        canon += varint(t)
        if t in (0x00,0x01): pass
        elif t in (0x02,0x03):
            canon += varint(f['largest'])+varint(f['delay'])+varint(f['count'])+varint(f['first'])
            for gap,rng in f['pairs']: canon += varint(gap)+varint(rng)
            if t==0x03: canon += b''.join(varint(v) for v in f['ecn'])
        elif t == 0x04: canon += varint(f['sid'])+varint(f['err'])+varint(f['fin'])
        elif t == 0x05: canon += varint(f['sid'])+varint(f['err'])
        elif t == 0x06: canon += varint(f['off'])+varint(f['ln'])+f['data']
        elif 0x08 <= t <= 0x0f:
            canon += varint(f['sid'])
            if f['hasoff']: canon += varint(f['off'])
            if f['haslen']: canon += varint(f['ln'])
            canon += f['data']
        elif t in (0x10,0x12,0x13,0x14,0x16,0x17): canon += varint(f['v'])
        elif t == 0x11: canon += varint(f['sid'])+varint(f['v'])
        elif t == 0x15: canon += varint(f['sid'])+varint(f['v'])
        elif t == 0x18: canon += varint(f['seq'])+varint(f['rpt'])+bytes([f['cl']])+f['cid']+f['tok']
        elif t == 0x19: canon += varint(f['seq'])
        elif t in (0x1a,0x1b): canon += f['data']
        elif t == 0x1c: canon += varint(f['ec'])+varint(f['tt'])+varint(f['rl'])+f['reason']
        elif t == 0x1d: canon += varint(f['ec'])+varint(f['rl'])+f['reason']
        elif t == 0x30: canon += f['data']
        elif t == 0x31: canon += varint(f['ln'])+f['data']
        if t in (0x1c,0x1d):
            return canon, start
    return canon, None

def stream_row(s):
    data = s['data']
    offs = sorted(data)
    ranges=[]
    for o in offs:
        if ranges and o == ranges[-1][1]: ranges[-1][1]=o+1
        else: ranges.append([o,o+1])
    prefix=0
    while prefix in data: prefix+=1
    return ranges, len(data), prefix, hashlib.sha256(bytes(data[i] for i in range(prefix))).hexdigest()
